package ama.api;
import ama.meeting.*;import ama.storage.*;import ama.transcript.*;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import ama.contract.MeetingContracts.*;import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Accepted original commands must not need later directory names; fresh current authorization still applies. */
public final class LocalMeetingReplayNameCheck {
 static final class Source extends AbstractDataSource {
  final DataSource delegate;boolean observe;int rawNames;Source(DataSource delegate){this.delegate=delegate;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> type,InvocationHandler h){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement statement)return proxy(statement,PreparedStatement.class,(s,sm,sa)->{if(observe&&sm.getName().equals("executeQuery")&&sql.contains(" FROM enterprise_identity ")){String projection=sql.substring(0,sql.indexOf(" FROM ")).replaceAll("(?i)OCTET_LENGTH\\(CONVERT\\(display_name USING utf16\\)\\)","0").replaceAll("(?i)(OCTET_LENGTH|CHAR_LENGTH)\\(display_name\\)","0");if(projection.matches("(?is).*\\bdisplay_name\\b.*")||projection.contains("*"))rawNames++;}return invoke(statement,sm,sa);});return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==2,"Explicit daily replay check required");Path file=Path.of(args[0]).toRealPath(),output=Path.of(args[1]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&output.startsWith(file.getParent().resolve("identity-replay"))&&Files.size(file)<65536,"Daily fresh evidence required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var j=new JdbcTemplate(source);j.setQueryTimeout(5);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));var original=j.queryForList("SELECT enterprise_id,display_name,status FROM enterprise_identity WHERE enterprise_id IN ('dev-owner','dev-member') ORDER BY enterprise_id");check(original.size()==2,"Exact owned test identities required");Files.writeString(output.resolve("identity-original.json"),new ObjectMapper().writeValueAsString(original),StandardOpenOption.CREATE_NEW);String wide="界🧪".repeat(1200000);var configured=ConfiguredProcessing.read(env);
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);var factory=new MeetingConfiguration();var repo=factory.meetingRepository(source,runtime.tx(),runtime.access(),runtime.fences(),runtime.outbox(),factory.companyMeetingCategories(),runtime.processing(),factory.workspaceReadLimits(env));String createKey=UUID.randomUUID().toString(),saveKey=UUID.randomUUID().toString(),confirmKey=UUID.randomUUID().toString();var created=repo.create(actor,createKey,UUID.randomUUID().toString());var request=new SaveInfo(created.revision(),"同原请求恢复验证",null,"真实服务命令建立；不是SQL业务夹具",java.time.LocalDate.of(2026,10,29),List.of("dev-member"),List.of());var saved=repo.save(actor,created.id(),saveKey,request,UUID.randomUUID().toString());var confirmRequest=new ConfirmRoster(saved.revision());var confirmed=repo.confirm(actor,created.id(),confirmKey,confirmRequest,UUID.randomUUID().toString());var before=LocalMeetingInfoRollbackCheck.snapshot(j,created.id());var results=new ArrayList<Map<String,Object>>();boolean newDenied=false,authorityDenied=false,mismatchedSaveDenied=false,mismatchedConfirmDenied=false;
   try{
    j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id='dev-member' AND status='ACTIVE'",wide);source.observe=true;
    for(String operation:List.of("SAVE","CONFIRM")){source.rawNames=0;boolean accepted=false;String failure="NONE";try{accepted=operation.equals("SAVE")?saved.equals(repo.save(actor,created.id(),saveKey,request,UUID.randomUUID().toString())):confirmed.equals(repo.confirm(actor,created.id(),confirmKey,confirmRequest,UUID.randomUUID().toString()));}catch(RuntimeException rejected){failure=rejected.getClass().getSimpleName();}results.add(Map.of("operation",operation,"originalAcceptedResult",accepted,"rawNameQueries",source.rawNames,"failure",failure));check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,created.id())),"Replay must create no business changes");}
    var changed=new SaveInfo(request.expectedRevision(),request.name()+"改写",null,request.summary(),request.occurredOn(),request.rosterDraftIds(),request.externalRosterNames());try{repo.save(actor,created.id(),saveKey,changed,UUID.randomUUID().toString());}catch(Conflict expected){mismatchedSaveDenied=true;}try{repo.confirm(actor,created.id(),confirmKey,new ConfirmRoster(confirmRequest.expectedRevision()+1),UUID.randomUUID().toString());}catch(Conflict expected){mismatchedConfirmDenied=true;}check(source.rawNames==0&&before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,created.id())),"Changed payload with accepted key cannot consume names or mutate business state");
    var next=new SaveInfo(confirmed.revision(),request.name(),null,request.summary(),request.occurredOn(),request.rosterDraftIds(),request.externalRosterNames());try{repo.save(actor,created.id(),UUID.randomUUID().toString(),next,UUID.randomUUID().toString());}catch(WorkspaceReadBudget.Unavailable expected){newDenied=true;}check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,created.id())),"New over-budget proposal has no effects");
    source.observe=false;for(var person:original)if(person.get("enterprise_id").equals("dev-member"))j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id=?",person.get("display_name"),person.get("enterprise_id"));j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id='dev-owner' AND status='ACTIVE'",wide);source.rawNames=0;source.observe=true;boolean accepted=false;String failure="NONE";try{accepted=created.equals(repo.create(actor,createKey,UUID.randomUUID().toString()));}catch(RuntimeException rejected){failure=rejected.getClass().getSimpleName();}results.add(Map.of("operation","CREATE","originalAcceptedResult",accepted,"rawNameQueries",source.rawNames,"failure",failure));check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,created.id())),"Create replay has no new root or child effects");
    source.observe=false;for(var person:original)if(person.get("enterprise_id").equals("dev-owner"))j.update("UPDATE enterprise_identity SET display_name=? WHERE enterprise_id=?",person.get("display_name"),person.get("enterprise_id"));j.update("UPDATE enterprise_identity SET status='DISABLED' WHERE enterprise_id='dev-owner' AND status='ACTIVE'");try{repo.save(actor,created.id(),saveKey,request,UUID.randomUUID().toString());}catch(ama.access.MeetingAccess.AccessDeniedException expected){authorityDenied=true;}check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,created.id())),"Fresh-authority denial has no effects");
   }finally{source.observe=false;for(var person:original)j.update("UPDATE enterprise_identity SET display_name=?,status=? WHERE enterprise_id=?",person.get("display_name"),person.get("status"),person.get("enterprise_id"));}
   boolean pass=results.size()==3&&results.stream().allMatch(r->Boolean.TRUE.equals(r.get("originalAcceptedResult"))&&((Integer)r.get("rawNameQueries"))==0)&&newDenied&&authorityDenied&&mismatchedSaveDenied&&mismatchedConfirmDenied&&original.equals(j.queryForList("SELECT enterprise_id,display_name,status FROM enterprise_identity WHERE enterprise_id IN ('dev-owner','dev-member') ORDER BY enterprise_id"));var report=Map.of("pass",pass,"meetingId",created.id(),"genuineFactoriesAndServiceCommands",true,"replays",results,"newNameProposalStillBudgetRejected",newDenied,"revokedActorStillDenied",authorityDenied,"identitiesRestored",true,"zeroReplayBusinessChanges",true,"changedPayloadStillConflicts",mismatchedSaveDenied&&mismatchedConfirmDenied);Files.writeString(output.resolve("report.json"),new ObjectMapper().writeValueAsString(report));System.out.println(new ObjectMapper().writeValueAsString(report));if(!pass)System.exit(1);
  }
 }
}
